#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

const int MAX_K=33,MOD=1000000007;

struct Matrix {
    long long a[MAX_K][MAX_K];
};

Matrix multiply(const Matrix &m1, const Matrix &m2, int size) {
    Matrix result = {};
    for (int i=0; i<=size; ++i)
        for (int j=0; j<=size; ++j) {
            result.a[i][j]=0;
            for (int p=0; p<=size; ++p)
                result.a[i][j]=(result.a[i][j]+m1.a[i][p]*m2.a[p][j])%MOD;
        }
    return result;
}

int main() {
    long long n;
    int k;
    cin >> n >> k;

    Matrix ans = {};
    for (int i=0; i<=k; ++i)
        ans.a[i][i]=1;

    vector<Matrix> t(k);
    for (int p=0; p<k; ++p) {
        for (int i=0; i<=k; ++i)
            for (int j=0; j<=k; ++j)
                t[p].a[i][j]= (i==j || i==p) ? 1 : 0;
    }

    vector<int> bits;
    for (long long temp=n; temp>0; temp/=k)
        bits.push_back(temp%k);
    bits.push_back(0);
    partial_sum(bits.rbegin(), bits.rend(), bits.rbegin());

    for (size_t p=0; p+1<bits.size(); ++p) {
        for (int i=bits[p]-1; i>=bits[p+1]; --i)
            ans = multiply(t[i%k], ans, k);
        vector<Matrix> pre(k), suf(k);
        pre[0]=t[0];
        for (int i=1; i<k; ++i)
            pre[i]=multiply(pre[i-1], t[i], k);
        suf[k-1]=t[k-1];
        for (int i=k-2; i>=0; --i)
            suf[i]=multiply(t[i], suf[i+1], k);
        ans = multiply(suf[0], ans, k);
        for (int i=1; i<k; ++i)
            ans = multiply(suf[i], pre[i-1], k);
    }

    long long total=0;
    for (int i=0; i<=k; ++i)
        total+=ans.a[i][k];
    cout << total%MOD << endl;
    return 0;
}
